CREATE TABLE "pc_users" ("id" uuid PRIMARY KEY, "email" text NOT NULL UNIQUE, "password_hash" text NOT NULL, "display_name" text NOT NULL, "status" text NOT NULL DEFAULT 'ACTIVE', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "pc_roles" ("id" uuid PRIMARY KEY, "name" text NOT NULL UNIQUE, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "pc_permissions" ("id" uuid PRIMARY KEY, "name" text NOT NULL UNIQUE, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "pc_user_roles" ("user_id" uuid NOT NULL REFERENCES "pc_users"("id") ON DELETE CASCADE, "role_id" uuid NOT NULL REFERENCES "pc_roles"("id") ON DELETE CASCADE, PRIMARY KEY ("user_id", "role_id"));
CREATE TABLE "pc_role_permissions" ("role_id" uuid NOT NULL REFERENCES "pc_roles"("id") ON DELETE CASCADE, "permission_id" uuid NOT NULL REFERENCES "pc_permissions"("id") ON DELETE CASCADE, PRIMARY KEY ("role_id", "permission_id"));
CREATE TABLE "pc_companies" ("id" uuid PRIMARY KEY, "name" text NOT NULL, "active" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "pc_branches" ("id" uuid PRIMARY KEY, "company_id" uuid NOT NULL REFERENCES "pc_companies"("id") ON DELETE RESTRICT, "name" text NOT NULL, "active" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now(), UNIQUE ("company_id", "name"));
CREATE TABLE "pc_user_branch_access" ("user_id" uuid NOT NULL REFERENCES "pc_users"("id") ON DELETE CASCADE, "branch_id" uuid NOT NULL REFERENCES "pc_branches"("id") ON DELETE CASCADE, PRIMARY KEY ("user_id", "branch_id"));
CREATE TABLE "pc_sessions" ("id" uuid PRIMARY KEY, "user_id" uuid NOT NULL REFERENCES "pc_users"("id") ON DELETE CASCADE, "token_hash" text NOT NULL UNIQUE, "expires_at" timestamptz NOT NULL, "revoked_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "pc_audit_logs" ("id" uuid PRIMARY KEY, "actor_id" uuid, "action" text NOT NULL, "resource" text NOT NULL, "entity_id" uuid, "company_id" uuid, "branch_id" uuid, "metadata" jsonb NOT NULL DEFAULT '{}', "occurred_at" timestamptz NOT NULL DEFAULT now()); CREATE INDEX "pc_audit_logs_company_occurred_idx" ON "pc_audit_logs" ("company_id", "occurred_at");
CREATE TABLE "pc_files" ("id" uuid PRIMARY KEY, "company_id" uuid, "storage_key" text NOT NULL UNIQUE, "content_type" text NOT NULL, "size" integer NOT NULL CHECK ("size" >= 0), "created_by" uuid, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "pc_notifications" ("id" uuid PRIMARY KEY, "user_id" uuid NOT NULL, "type" text NOT NULL, "payload" jsonb NOT NULL DEFAULT '{}', "read_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now()); CREATE INDEX "pc_notifications_user_read_idx" ON "pc_notifications" ("user_id", "read_at");
CREATE TABLE "pc_configuration" ("key" text PRIMARY KEY, "value" jsonb NOT NULL, "updated_at" timestamptz NOT NULL DEFAULT now());
